create function pg_temp.ordered(snapshot jsonb) returns jsonb language sql as $$
 select jsonb_object_agg(key,(select coalesce(jsonb_agg(v order by v::text),'[]') from jsonb_array_elements(value) v)) from jsonb_each(snapshot);
$$;
create function pg_temp.safe_value(path text,value jsonb) returns jsonb language plpgsql as $$
declare clean jsonb;
begin
 if path ~* 'password|secret|token|authorization|cookie|credential|api_key|apikey|email|meta_data|narrative|note|reason|title|description|instructions|body|real_name|bio|major|music|food|weird|instagram|prompts|public_place' then return to_jsonb('<redacted>'::text);end if;
 if value is null then return to_jsonb('<absent>'::text);end if;
 if jsonb_typeof(value)='object' then
   select coalesce(jsonb_object_agg(key,pg_temp.safe_value(path||'.'||key,v)),'{}') into clean from jsonb_each(value) q(key,v);return clean;
 elsif jsonb_typeof(value)='array' then
   select coalesce(jsonb_agg(pg_temp.safe_value(path||'.'||(n-1)::text,v) order by n),'[]') into clean from jsonb_array_elements(value) with ordinality q(v,n);return clean;
 elsif jsonb_typeof(value)='string' then
   return to_jsonb(regexp_replace(regexp_replace(value#>>'{}','eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+','<redacted-token>','g'),'(postgres(ql)?://)[^@[:space:]]+@','\1<redacted>@','gi'));
 end if;return value;
end;$$;
create function pg_temp.diff(e jsonb,a jsonb,path text default '$') returns jsonb language plpgsql as $$
declare k text; delta jsonb:='[]';
begin
 if e is not distinct from a then return delta; end if;
 if jsonb_typeof(e)='object' and jsonb_typeof(a)='object' then
   for k in select key from jsonb_object_keys(e) key union select key from jsonb_object_keys(a) key loop
     delta:=delta||pg_temp.diff(e->k,a->k,path||'.'||k);
   end loop;
 elsif jsonb_typeof(e)='array' and jsonb_typeof(a)='array' then
   for k in select generate_series(0,greatest(jsonb_array_length(e),jsonb_array_length(a))-1)::text loop
     delta:=delta||pg_temp.diff(e->k::int,a->k::int,path||'.'||k);
   end loop;
 else delta:=jsonb_build_array(jsonb_build_object('field',path,'expected',pg_temp.safe_value(path,e),'actual',pg_temp.safe_value(path,a)));
 end if;
 return delta;
end;$$;
create function pg_temp.check54(e jsonb,a jsonb,phase text) returns boolean language plpgsql as $$
declare delta jsonb; fixture jsonb;
begin
 if (select count(*) from jsonb_object_keys(e))<>54 or (select count(*) from jsonb_object_keys(a))<>54 then
   raise exception 'Operator full54 shape invalid'; end if;
 delta:=pg_temp.diff(pg_temp.ordered(e),pg_temp.ordered(a));
 if delta<>'[]'::jsonb then
   select f into fixture from operator_context;
   raise notice 'Operator failed evidence before rollback: %',jsonb_build_object('id',fixture->>'id','phase',phase,'partition','failed-no-credit','differences',delta,'lock_observation',null,'raw_census_withheld',true);
   return false;
 end if;return true;
end;$$;
create function pg_temp.result_check(e jsonb,a jsonb) returns boolean language plpgsql as $$
begin
 if e is distinct from a then
   raise notice 'Operator full result mismatch: %',pg_temp.diff(e,a,'$.public_result');return false;
 end if;return true;
end;$$;
create function pg_temp.setup_expected(clean jsonb,f jsonb,t timestamptz) returns jsonb language plpgsql as $$
declare e jsonb:=clean; actor uuid:=(f->>'actor')::uuid; reporter uuid:=(f->>'reporter')::uuid; target uuid:=(f->>'target')::uuid;
 report uuid:=(f->>'report')::uuid; source uuid:=(f->>'source')::uuid; is_hangout boolean:=(f->>'hangout')::boolean;
 target_id uuid; target_type text; rows jsonb;
begin
 target_id:=case when is_hangout then source else target end;target_type:=case when is_hangout then 'hangout' else 'user' end;
 select jsonb_agg(jsonb_build_object('id',id,'email','operator-'||id::text||'@unc.edu','email_confirmed_at',null,'deleted_at',null,'raw_user_meta_data',null,'raw_app_meta_data',null)) into rows from unnest(array[actor,reporter,target]) id;
 e:=jsonb_set(e,array['auth.users'],rows);
 select jsonb_agg(jsonb_build_object('id',id,'status','active','created_at',t)) into rows from unnest(array[actor,reporter,target]) id;
 e:=jsonb_set(e,array['public.accounts'],rows);
 select jsonb_agg(jsonb_build_object('user_id',id,'real_name',null,'graduation_year',null,'major',null,'bio',null,'primary_photo_path',null,'is_complete',false,'created_at',t,'interests','[]'::jsonb,'down_to_do','[]'::jsonb,'favorite_music',null,'favorite_foods',null,'weird_fact',null,'prompts','[]'::jsonb,'instagram',null,'additional_photo_paths','[]'::jsonb,'revision',1)) into rows from unnest(array[actor,reporter,target]) id;
 e:=jsonb_set(e,array['public.profiles'],rows);
 e:=jsonb_set(e,array['public.platform_roles'],jsonb_build_array(jsonb_build_object('user_id',actor,'role','moderator','created_at',t)));
 e:=jsonb_set(e,array['private.moderation_feature_gate'],'[{"singleton":true,"enabled":true}]');
 e:=jsonb_set(e,array['private.safety_reports'],jsonb_build_array(jsonb_build_object('id',report,'submitted_at',t,'reporter_id',reporter,'target_type',target_type,'target_id',target_id,'category','harassment','narrative','Undisclosed operator narrative','provenance_kind',case when is_hangout then 'current_hangout' else 'current_people' end,'provenance_ref_id',target_id)));
 e:=jsonb_set(e,array['private.safety_report_requests'],jsonb_build_array(jsonb_build_object('reporter_id',reporter,'request_id',(f->>'intake_request')::uuid,'input_fingerprint',md5(jsonb_build_array(target_type,target_id,'harassment','Undisclosed operator narrative')::text),'report_id',report)));
 if f->>'caller' in ('apply_account_moderation_action','apply_hangout_moderation_action') then
 e:=jsonb_set(e,array['private.moderation_cases'],jsonb_build_array(jsonb_build_object('report_id',report,'state','in_review','revision',1,'note',null,'disposition',null,'duplicate_report_id',null,'sanction_id',null,'hangout_disable_id',null)));end if;
 if is_hangout then
 e:=jsonb_set(e,array['public.hangouts'],jsonb_build_array(jsonb_build_object('id',source,'university_id','00000000-0000-4000-8000-000000000001'::uuid,'host_id',target,'title','Undisclosed operator fixture','description',null,'starts_at',t+interval '1 day','ends_at',null,'status','published','joining_state','open','visibility','campus','public_place','Approximate','public_latitude',35.91,'public_longitude',-79.05,'campus_zone',null,'location_precision','approximate_area','revision',1,'created_at',t,'updated_at',t)));
 e:=jsonb_set(e,array['public.hangout_participants'],jsonb_build_array(jsonb_build_object('hangout_id',source,'account_id',target,'state','joined','joined_at',t,'left_at',null,'removed_at',null,'updated_at',t)));
 e:=jsonb_set(e,array['public.hangout_private_locations'],jsonb_build_array(jsonb_build_object('hangout_id',source,'instructions','Undisclosed operator instructions','updated_at',t)));
 end if;return e;
end;$$;
create function pg_temp.expected_result(f jsonb,b jsonb) returns jsonb language plpgsql as $$
declare r jsonb:=b->'private.safety_reports'->0; base jsonb; caller text:=f->>'caller';
begin
 base:=jsonb_build_object('report_id',r->'id','submitted_at',r->'submitted_at','target_type',r->'target_type','target_id',r->'target_id','reporter_id',r->'reporter_id','category','harassment','case_state','open');
 if caller='list_moderation_reports' then return jsonb_build_array(base);end if;
 if caller='get_moderation_report' then return jsonb_build_array(base||jsonb_build_object('case_revision',0,'narrative',r->'narrative','provenance_kind',r->'provenance_kind','provenance_ref_id',r->'provenance_ref_id','case_note',null,'disposition',null,'target_status','active','target_campus_id',null,'target_disabled',null));end if;
 if caller='transition_moderation_case' then return '[{"case_state":"in_review","revision":1}]';end if;
 if caller='apply_account_moderation_action' then return '[{"case_state":"closed","revision":2,"account_status":"suspended"}]';end if;
 return '[{"case_state":"closed","revision":2,"target_disabled":true}]';
end;$$;
create function pg_temp.success_expected(b jsonb,a jsonb,f jsonb,started timestamptz) returns jsonb language plpgsql as $$
declare e jsonb:=b; audit jsonb:=a->'private.moderation_audit'->0; v jsonb; expected_audit jsonb;
 caller text:=f->>'caller'; actor uuid:=(f->>'actor')::uuid; report uuid:=(f->>'report')::uuid; target uuid:=(f->>'target')::uuid; source uuid:=(f->>'source')::uuid; request uuid:=(f->>'request')::uuid;
 transition boolean:=caller='transition_moderation_case'; hangout boolean:=caller='apply_hangout_moderation_action'; evidence uuid; fp text;
begin
 if jsonb_array_length(a->'private.moderation_audit')<>1 or (audit->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 or (audit->>'occurred_at')::timestamptz not between started and clock_timestamp() then raise exception 'Operator audit generated binding invalid';end if;
 expected_audit:='{"id":null,"occurred_at":null,"operator_id":null,"action":null,"report_id":null,"subject_target_type":null,"subject_target_id":null,"subject_campus_id":null,"request_id":null,"previous_state":null,"new_state":null,"previous_revision":null,"new_revision":null,"reason":null,"duplicate_report_id":null,"page_report_ids":null,"page_count":null,"sanction_id":null,"previous_account_status":null,"new_account_status":null,"hangout_disable_id":null,"previous_hangout_disabled":null,"new_hangout_disabled":null}';
 expected_audit:=expected_audit||jsonb_build_object('id',audit->'id','occurred_at',audit->'occurred_at','operator_id',actor);
 if caller in ('list_moderation_reports','get_moderation_report') then
   if (audit->>'request_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'Operator read request binding invalid';end if;
   expected_audit:=expected_audit||jsonb_build_object('request_id',audit->'request_id','action',case when caller='list_moderation_reports' then 'queue_read' else 'detail_read' end);
   if caller='list_moderation_reports' then expected_audit:=expected_audit||jsonb_build_object('page_report_ids',jsonb_build_array(report),'page_count',1);else expected_audit:=expected_audit||jsonb_build_object('report_id',report);end if;
 else
   fp:=case when transition then md5(jsonb_build_array(report,0,'start_review',null,null)::text)
     when hangout then 'hangout:'||md5(jsonb_build_array(report,1,'Operator fixture reason')::text)
     else 'account:'||md5(jsonb_build_array(report,1,'suspend','Operator fixture reason')::text) end;
   e:=jsonb_set(e,array['private.moderation_requests'],jsonb_build_array(jsonb_build_object('operator_id',actor,'request_id',request,'fingerprint',fp,'report_id',report,'result_state',case when transition then 'in_review' else 'closed' end,'result_revision',case when transition then 1 else 2 end)));
   v:=jsonb_build_object('report_id',report,'state',case when transition then 'in_review' else 'closed' end,'revision',case when transition then 1 else 2 end,'note',case when transition then null else 'Operator fixture reason' end,'disposition',case when transition then null else 'action_taken' end,'duplicate_report_id',null,'sanction_id',null,'hangout_disable_id',null);
   expected_audit:=expected_audit||jsonb_build_object('action',case when transition then 'start_review' when hangout then 'disable_hangout' else 'suspend' end,'report_id',report,'subject_target_type',case when hangout then 'hangout' else 'user' end,'subject_target_id',case when hangout then source else target end,'subject_campus_id',case when hangout then '00000000-0000-4000-8000-000000000001'::uuid else null end,'request_id',request,'previous_state',case when transition then 'open' else 'in_review' end,'new_state',case when transition then 'in_review' else 'closed' end,'previous_revision',case when transition then 0 else 1 end,'new_revision',case when transition then 1 else 2 end,'reason',case when transition then null else 'Operator fixture reason' end);
   if not transition then
     if hangout then
       audit:=a->'private.hangout_disables'->0;evidence:=(audit->>'id')::uuid;
       if jsonb_array_length(a->'private.hangout_disables')<>1 then raise exception 'Operator disable cardinality invalid';end if;
     else
       audit:=a->'private.account_sanctions'->0;evidence:=(audit->>'id')::uuid;
       if jsonb_array_length(a->'private.account_sanctions')<>1 then raise exception 'Operator sanction cardinality invalid';end if;
     end if;
     if evidence::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or (audit->>'occurred_at')::timestamptz not between started and clock_timestamp() then raise exception 'Operator action generated binding invalid';end if;
     if hangout then
       e:=jsonb_set(e,array['private.hangout_disables'],jsonb_build_array(jsonb_build_object('id',evidence,'report_id',report,'subject_type','hangout','hangout_id',source,'operator_id',actor,'request_id',request,'previous_disabled',false,'new_disabled',true,'subject_campus_id','00000000-0000-4000-8000-000000000001'::uuid,'reason','Operator fixture reason','occurred_at',audit->'occurred_at')));
       v:=v||jsonb_build_object('hangout_disable_id',evidence);expected_audit:=expected_audit||jsonb_build_object('hangout_disable_id',evidence,'previous_hangout_disabled',false,'new_hangout_disabled',true);
     else
       e:=jsonb_set(e,array['private.account_sanctions'],jsonb_build_array(jsonb_build_object('id',evidence,'report_id',report,'subject_type','user','subject_id',target,'operator_id',actor,'request_id',request,'action','suspend','previous_status','active','new_status','suspended','subject_campus_id',null,'reason','Operator fixture reason','occurred_at',audit->'occurred_at')));
       v:=v||jsonb_build_object('sanction_id',evidence);expected_audit:=expected_audit||jsonb_build_object('sanction_id',evidence,'previous_account_status','active','new_account_status','suspended');
       e:=jsonb_set(e,array['public.accounts'],(select jsonb_agg(case when row->>'id'=target::text then row||'{"status":"suspended"}'::jsonb else row end) from jsonb_array_elements(b->'public.accounts') row));
     end if;
   end if;
   e:=jsonb_set(e,array['private.moderation_cases'],jsonb_build_array(v));
 end if;
 return jsonb_set(e,array['private.moderation_audit'],jsonb_build_array(expected_audit));
end;$$;
create function pg_temp.loss_expected(b jsonb,f jsonb) returns jsonb language plpgsql as $$
declare e jsonb:=b; loss text:=f->>'loss'; actor text:=f->>'actor'; t text; rows jsonb;
begin
 if loss='gate_missing' then e:=jsonb_set(e,array['private.moderation_feature_gate'],'[]');
 elsif loss='gate_off' then e:=jsonb_set(e,array['private.moderation_feature_gate'],'[{"singleton":true,"enabled":false}]');
 elsif loss in ('role_missing','role_nonoperator') then e:=jsonb_set(e,array['public.platform_roles'],'[]');
 elsif loss='account_missing' then
   e:=jsonb_set(e,array['public.platform_roles'],'[]');
   foreach t in array array['public.accounts','public.profiles','public.university_memberships'] loop
     select coalesce(jsonb_agg(row),'[]') into rows from jsonb_array_elements(b->t) row where coalesce(row->>'id',row->>'user_id')<>actor;
     e:=jsonb_set(e,array[t],rows);
   end loop;
 else
   select jsonb_agg(case when row->>'id'=actor then row||jsonb_build_object('status',case when loss='account_suspended' then 'suspended' else 'banned' end) else row end) into rows from jsonb_array_elements(b->'public.accounts') row;
   e:=jsonb_set(e,array['public.accounts'],rows);
 end if;return e;
end;$$;
